import io from 'socket.io-client'
import {
  recordSocketEvent,
  payloadSize,
  setSocketConnected
} from './telemetry'

/**
 * Error codes produced by `SocketManager.request()`.
 *
 * They let the caller tell a **transport** failure (the answer never arrived)
 * from a **payload** failure (the server answered with an `error`): only the
 * former is worth retrying, e.g. over HTTP.
 */
export const SOCKET_ERROR_CODES = {
  /** No socket instance at all (user not logged in / never connected). */
  notConnected: 'SOCKET_NOT_CONNECTED',
  /** The socket instance exists but is not connected right now. */
  offline: 'SOCKET_OFFLINE',
  /** The response event did not arrive within the timeout. */
  timeout: 'SOCKET_TIMEOUT',
  /** The socket dropped (or was replaced) while the request was in flight. */
  disconnected: 'SOCKET_DISCONNECTED',
  /** The server answered, but the payload carried an `error` message. */
  response: 'SOCKET_RESPONSE_ERROR'
}

/** Default time a `request()` waits for its response event, in milliseconds. */
export const DEFAULT_REQUEST_TIMEOUT = 30000

/** Counter used to build unique request ids. */
let _requestCounter = 0

/**
 * Build a request id, unique within the browser session.
 *
 * @returns {string} Id such as `sio-lq3f9k-12-a1b2c3`.
 */
function nextRequestId() {
  _requestCounter += 1
  return `sio-${Date.now().toString(36)}-${_requestCounter}-${Math.random().toString(36).slice(2, 8)}`
}

/**
 * Build an error carrying the socket `code` plus `isSocketTransport`.
 *
 * `isSocketTransport` is `true` when the request never produced an answer
 * (offline, timeout, disconnect) and `false` when the server answered with an
 * `error` field, which is a real result and must be propagated untouched.
 *
 * @param {string} message - Error message.
 * @param {string} code - One of `SOCKET_ERROR_CODES`.
 * @returns {Error} Error to reject the request with.
 */
function socketError(message, code) {
  const error = new Error(message)
  error.code = code
  error.isSocketTransport = code !== SOCKET_ERROR_CODES.response
  return error
