  constructor({ onEvent, onConnect, onDisconnect } = {}) {
    this._socket = null
    this._onEvent = onEvent || (() => {})
    this._onConnect = onConnect || (() => {})
    this._onDisconnect = onDisconnect || (() => {})
    this._listeners = new Map()
    /**
