    this._pending = new Map()
  }

  get id() {
    return this._socket?.id || null
  }

  get connected() {
    return this._socket?.connected || false
  }

  get socket() {
    return this._socket
  }

  /** Number of requests waiting for their response event. */
  get pendingRequests() {
    return this._pending.size
