  connect() {
    if (this._socket) {
      // Pending requests belong to the socket being replaced: their answer would
      // arrive on the old session id, which is gone.
      this._rejectPending(
        '[SocketManager] socket replaced, pending requests dropped',
        SOCKET_ERROR_CODES.disconnected
      )
      this._socket.close()
      this._socket = null
    }

    const socket = io({
      path: '/api/socket.io',
      reconnectionDelayMax: 5000,
      transports: ['websocket']
    })

    socket.on('connect_error', (err) => {
      console.warn('[SocketManager] connect_error:', err.message)
      recordSocketEvent({
        event: 'connect_error',
        direction: 'system',
        error: err?.message || 'connect_error',
        socketId: socket.id
      })
    })

    socket.on('connect', () => {
      console.log('[SocketManager] connected', socket.id)
      setSocketConnected(true, socket.id)
      recordSocketEvent({
        event: 'connect',
        direction: 'system',
        detail: socket.io?.engine?.transport?.name || null,
        socketId: socket.id
      })
      this._onConnect(socket.id)
    })

    socket.on('disconnect', (reason) => {
      console.log('[SocketManager] disconnected')
      setSocketConnected(false)
      recordSocketEvent({
        event: 'disconnect',
        direction: 'system',
        detail: reason || null,
        socketId: socket.id
      })
      // The server lost this session: the response events in flight will never
      // arrive. Reject them now so the callers can fall back (e.g. to HTTP)
      // instead of waiting for their timeout.
      this._rejectPending(
        `[SocketManager] socket disconnected while waiting for a response${reason ? ` (${reason})` : ''}`,
        SOCKET_ERROR_CODES.disconnected
      )
      this._onDisconnect()
    })

    socket.io.on('reconnect', (attempt) => {
      console.log('[SocketManager] reconnected', socket.id)
      setSocketConnected(true, socket.id)
      recordSocketEvent({
        event: 'reconnect',
        direction: 'system',
        detail: attempt ? `attempt ${attempt}` : null,
        socketId: socket.id
      })
      this._onConnect(socket.id)
    })

    socket.onAny((event, ...args) => {
      // Size of the whole argument list: the server may send more than one.
      recordSocketEvent({
        event,
        direction: 'in',
        size: payloadSize(args),
        socketId: socket.id
      })
      const payload = args[0]
      // Responses of a `request()` are consumed here and never forwarded to the
      // app event bus: they are broadcast to every client and only mean
      // something to the caller that matched them by request id.
      if (this._resolvePending(event, payload)) return
      this._onEvent({ event, data: payload })
    })

    // Re-attach any named listeners registered before connect
    this._listeners.forEach((handler, event) => {
      socket.on(event, handler)
    })

    this._socket = socket
    return this
  }

  /**
   * Disconnect and destroy the current socket.
   */
  disconnect() {
    if (this._socket) {
      this._rejectPending(
        '[SocketManager] socket closed, pending requests dropped',
        SOCKET_ERROR_CODES.disconnected
      )
      recordSocketEvent({
        event: 'close',
        direction: 'system',
