  emit(event, data, ack) {
    const socket = this._socket

    if (!socket) {
      console.warn('[SocketManager] emit called but socket is not connected')
      recordSocketEvent({
        event,
        direction: 'out',
        size: payloadSize(data),
        error: 'socket not connected'
      })
      return
    }

    if (typeof ack === 'function') {
      // The ack round trip is the only per-event latency this side can measure:
      // record it so a slow handler shows up in the socket table.
      const startedAt = typeof performance !== 'undefined' ? performance.now() : Date.now()
      socket.emit(event, data, (...ackArgs) => {
        const elapsed = (typeof performance !== 'undefined' ? performance.now() : Date.now()) - startedAt
        recordSocketEvent({
          event,
          direction: 'out',
          size: payloadSize(data),
          durationMs: elapsed,
          error: ackArgs[0]?.error || null,
          socketId: socket.id
        })
        ack(...ackArgs)
      })
    } else {
      recordSocketEvent({
        event,
        direction: 'out',
        size: payloadSize(data),
        socketId: socket.id
      })
      socket.emit(event, data)
    }
  }

  /**
   * Send a request event and wait for its response event.
   *
   * The `request_id` is added to the payload (and echoed back by the server), so
   * several requests of the same kind can be in flight at once and the broadcast
   * responses are dispatched to the right caller.
   *
   * The promise **rejects** when the server answers with an `error` field, and
   * when the answer cannot arrive (not connected, timeout, disconnect); in the
   * latter case `error.isSocketTransport === true`.
   *
   * @param {string} event - Request event name (`codx-junior-file-read`, ...).
   * @param {Object} [data] - Request payload.
   * @param {Object} options - Protocol options.
   * @param {string} options.responseEvent - Event that carries the answer.
   * @param {number} [options.timeout] - Give up after this many ms.
   * @param {string} [options.requestId] - Explicit id (a unique one is generated).
   * @returns {Promise<Object>} Response payload (`{ request_id, ... , result }`).
   *
   * @example
   * const response = await socket.request('codx-junior-file-diff', {
   *   codx_path: project.codx_path,
   *   path: 'src/main.js',
   *   content
   * }, { responseEvent: 'codx-junior-file-diff-response' })
   * console.log(response.result.diff)
   */
  request(event, data = {}, { responseEvent, timeout = DEFAULT_REQUEST_TIMEOUT, requestId } = {}) {
    if (!responseEvent) {
      throw new Error(`[SocketManager] ${event}: "responseEvent" is required`)
    }
    if (!this._socket) {
      return Promise.reject(socketError(
        `[SocketManager] ${event}: socket is not connected`,
        SOCKET_ERROR_CODES.notConnected
      ))
    }
    if (!this._socket.connected) {
      return Promise.reject(socketError(
        `[SocketManager] ${event}: socket is offline`,
        SOCKET_ERROR_CODES.offline
      ))
    }

    const id = requestId || nextRequestId()

    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this._pending.delete(id)
        reject(socketError(
          `[SocketManager] ${event}: no response after ${timeout}ms`,
          SOCKET_ERROR_CODES.timeout
        ))
      }, timeout)
      // Node timers must not keep the process alive (no-op in the browser).
      if (timer && typeof timer.unref === 'function') timer.unref()

      this._pending.set(id, { event, responseEvent, timer, resolve, reject })

      try {
        this.emit(event, { ...data, request_id: id })
      } catch (ex) {
        clearTimeout(timer)
        this._pending.delete(id)
        reject(socketError(
          `[SocketManager] ${event}: ${ex?.message || ex}`,
          SOCKET_ERROR_CODES.notConnected
        ))
      }
    })
  }

  /**
   * Register a named event listener.
   * Persists across reconnects.
   * @param {string} event
   * @param {Function} handler
   */
  on(event, handler) {
    this._listeners.set(event, handler)
    if (this._socket) {
      this._socket.on(event, handler)
    }
  }

  /**
   * Remove a named event listener.
   * @param {string} event
   */
  off(event) {
    this._listeners.delete(event)
    if (this._socket) {
      this._socket.off(event)
    }
  }

  /**
   * Settle the pending request a response belongs to.
   *
   * Responses are **broadcast**: every connected client receives them, so the
   * `request_id` (plus the expected response event) is the only way to know
   * which call the payload answers.
   *
   * @param {string} event - Received event name.
   * @param {Object} payload - Received payload.
   * @returns {boolean} `true` when the payload was consumed by a pending request.
   * @private
   */
  _resolvePending(event, payload) {
    if (!this._pending.size) return false

    const id = payload?.request_id || payload?.requestId
    if (!id) return false

    const pending = this._pending.get(id)
    if (!pending || pending.responseEvent !== event) return false

    this._pending.delete(id)
    clearTimeout(pending.timer)

    if (payload.error) {
      pending.reject(socketError(String(payload.error), SOCKET_ERROR_CODES.response))
    } else {
      pending.resolve(payload)
    }
    return true
  }

  /**
   * Reject every request waiting for a response.
   *
   * @param {string} message - Error message.
   * @param {string} code - One of `SOCKET_ERROR_CODES`.
   * @returns {number} Number of rejected requests.
   * @private
   */
  _rejectPending(message, code) {
    if (!this._pending.size) return 0

    const pending = [...this._pending.values()]
    this._pending.clear()
    pending.forEach(({ timer, reject }) => {
      clearTimeout(timer)
      reject(socketError(message, code))
    })
    return pending.length
  }
}
