import { CACHE_TTL, hashString, normalizePath } from '../requestCache'
import { QUEUE_NAMES } from '../requestQueue'

/**
 * Files API module
 * Handles file operations: list, read, search, upload, binary download/preview
 *
 * ## `read` and `diff` go through the socket
 *
 * `GET /api/files/read` and `POST /api/files/diff` are the expensive calls of the
 * editor / diff views. On a large file they keep an HTTP worker busy for a while
 * and the answer arrives too late for the UI. Both operations are therefore sent
 * over the existing Socket.IO connection, using the events registered by the
 * backend:
 *
 * | Request event (client → server) | Response event (server → client)  | Resolves with |
 * |---------------------------------|-----------------------------------|---------------|
 * | `codx-junior-file-read`         | `codx-junior-file-read-response`  | `{ content, is_binary, last_modification, size, ... }` |
 * | `codx-junior-file-diff`         | `codx-junior-file-diff-response`  | `{ diff, stats, last_modification, size }` |
 *
 * Both handlers run server-side in a worker pool, so nothing blocks the HTTP
 * request path; they answer later with a dedicated event that carries the
 * `request_id` of the request. `SocketManager.request()` (`api/socket.js`) does
 * the correlation and resolves with `result`, or rejects with the server error:
 *
 * ```js
 * // payloads
 * { request_id, path, result: { ... } }   // success
 * { request_id, path, error: 'File not found: src/a.js' } // failure
 * ```
 *
 * This is transparent for the callers: `read()` and `diff()` keep returning the
 * same values as the HTTP endpoints did.
 *
 * ### Fallback
 *
 * The HTTP endpoints are still used when:
 *  - the socket is not connected (not logged in yet, reconnecting…), or
 *  - the answer never arrives (timeout, disconnect) — a *transport* failure. A
 *    payload error (`File not found`, `Access denied`) is a real answer and is
 *    propagated without retrying.
 *
 * Pass `transport: 'http'` to force the HTTP endpoint.
 *
 * ### Cache and queues (unchanged)
 *
 * Both callers share the short-term cache and the request queues with every
 * other caller, whichever transport ends up being used:
 *
 *  - an identical `read` / `diff` is served from the cache for a few seconds (a
 *    diff is keyed by a hash of its content),
 *  - a caller arriving while the request is running waits for it instead of
 *    starting a second one,
 *  - **different** reads and diffs are queued (`files:read` / `files:diff`, one
 *    at a time) so a re-rendered diff panel cannot flood the backend worker pool,
 *  - `force: true` bypasses the entry for an explicit refresh.
 *
 * Keys are built from the **normalized** path: `./src/a.js`, `src/a.js` and
 * `src//a.js` are one file, so they share an entry — and a write through any of
 * those spellings invalidates all of them.
 */

/** Socket.IO events backing `read` and `diff`. */
const SOCKET_FILE_EVENTS = {
  read: {
    request: 'codx-junior-file-read',
    response: 'codx-junior-file-read-response'
  },
  diff: {
    request: 'codx-junior-file-diff',
    response: 'codx-junior-file-diff-response'
  }
}

/**
 * Time `read` / `diff` wait for the socket answer before falling back to HTTP.
 * Reading a big file or diffing a large content can legitimately take a while.
 */
const SOCKET_TIMEOUT_MS = 60000

/**
 * Build the cache key of a file entry.
 *
 * @param {Object} API - API instance.
 * @param {string} kind - Entry family (`files:read`, `files:diff`).
 * @param {string} path - Project relative (or absolute) path.
 * @param {...string} parts - Extra key parts.
 * @returns {string} Cache key.
 */
function fileKey(API, kind, path, ...parts) {
  return API.cacheKey(kind, normalizePath(path), ...parts)
}

/**
 * Invalidate every cached entry of a file (content and diffs).
 *
 * Matches on the `|path|` segment of the key, so all the families of that path
 * (`files:read`, `files:diff` with any branch/content hash) are dropped at once.
 *
 * @param {Object} API - API instance.
 * @param {string} path - Project relative path.
