 * socket cannot be used — the caller must then go through HTTP.
 */
function overSocket(API, events, data) {
  const socket = API.socket
  if (!socket || !socket.connected) return null

  return socket.request(events.request, {
    // Required by the server to build the project session.
    codx_path: API.activeProject?.codx_path,
    ...data
  }, {
    responseEvent: events.response,
    timeout: SOCKET_TIMEOUT_MS
  }).then((response) => response?.result)
}

/**
 * `true` when the error means the socket could not deliver an answer, i.e. the
 * call is worth retrying over HTTP. A payload error (`File not found`,
 * `Access denied`) is a real answer and must be propagated untouched.
