function withHttpFallback(label, socketRequest, httpRequest) {
  if (!socketRequest) return httpRequest()

  return socketRequest.catch((error) => {
    if (!isTransportError(error)) throw error
    console.warn(
      `[files] ${label} over socket failed (${error.code}), retrying over HTTP:`,
      error.message
    )
    return httpRequest()
  })
